// Installs this checkout's build as the Codex plugin, or removes it:
//   npm run dev:plugin -- install|update|uninstall
// install and update build, assemble release/ and install it from a local
// marketplace. uninstall removes the plugin and that marketplace. Task data
// lives outside the plugin, so it stays. See
// docs/development.md#install-a-local-build.
import { execFileSync, spawnSync } from "node:child_process";
import { existsSync, readFileSync, realpathSync } from "node:fs";
import { resolve } from "node:path";

const [operation] = process.argv.slice(2);

if (!["install", "update", "uninstall"].includes(operation)) {
  console.error("Usage: npm run dev:plugin -- install|update|uninstall");
  process.exit(1);
}

const marketplace = JSON.parse(
  readFileSync(".agents/plugins/marketplace.json", "utf8"),
).name;

const { name } = JSON.parse(readFileSync("package.json", "utf8"));
const plugin = `${name}@${marketplace}`;
const release = resolve("release");
const codex = process.env.CODEX_BIN || "codex";

// Under npm, its own script runs through this Node, as in assemble-release.mjs.
const npmCli = process.env.npm_execpath;
const npm = npmCli?.endsWith(".js") ? [process.execPath, npmCli] : ["npm"];

/** Runs a command with its output shown, and exits with its status on failure. */
function run(command, args) {
  const { status, error } = spawnSync(command, args, { stdio: "inherit" });

  if (error) throw error;
  if (status !== 0) process.exit(status ?? 1);
}

/** The configured marketplace with this checkout's marketplace name, if any. */
function configuredMarketplace() {
  const { marketplaces } = JSON.parse(
    execFileSync(codex, ["plugin", "marketplace", "list", "--json"], {
      encoding: "utf8",
    }),
  );

  return marketplaces.find((entry) => entry.name === marketplace);
}

/**
 * Removes the plugin and the marketplace. `plugin remove` succeeds when the
 * plugin is absent and also clears an entry whose marketplace is gone, which
 * `plugin list` doesn't report, so it always runs.
 */
function uninstall(existing) {
  run(codex, ["plugin", "remove", plugin]);

  if (existing) run(codex, ["plugin", "marketplace", "remove", marketplace]);
}

const isLocalRelease = (entry) =>
  entry.marketplaceSource.sourceType === "local" &&
  existsSync(release) &&
  realpathSync(entry.marketplaceSource.source) === realpathSync(release);

if (operation === "uninstall") {
  const existing = configuredMarketplace();

  if (existing && !isLocalRelease(existing)) {
    console.log(
      `Marketplace ${marketplace} comes from ${existing.marketplaceSource.source}, not this checkout. Removing it too.`,
    );
  }

  uninstall(existing);
  console.log(`Uninstalled ${plugin}. Task data is kept.`);
  process.exit(0);
}

// Build before touching the installation, so a failed build leaves it working.
run(npm[0], [...npm.slice(1), "run", "build"]);
run(process.execPath, ["scripts/assemble-release.mjs"]);

const existing = configuredMarketplace();

// Codex refuses a second source under the same name, such as the published
// marketplace, so replace it.
if (existing && !isLocalRelease(existing)) {
  console.log(
    `Replacing marketplace ${marketplace} from ${existing.marketplaceSource.source}. Re-add it after uninstalling to return to it.`,
  );

  uninstall(existing);
}

if (!existing || !isLocalRelease(existing)) {
  run(codex, ["plugin", "marketplace", "add", release]);
}

// Reinstalling the same version replaces the cached copy.
run(codex, ["plugin", "add", plugin]);

console.log(`
Installed ${plugin} from ${release}.
Restart Codex to load the new proxy, skills and panel. A running service
keeps its code when the version is unchanged. To run the new service, stop it
(the pid in its service.json). That interrupts its running turns.`);

