import assert from "node:assert/strict";
import { execFile, execFileSync } from "node:child_process";
import {
  chmod,
  copyFile,
  cp,
  mkdir,
  mkdtemp,
  readdir,
  readFile,
  realpath,
  rm,
  writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { promisify } from "node:util";

import { describe, test, type TestContext } from "vitest";

const exec = promisify(execFile);
const plugin = "subagent-extension-for-codex@demo-user";

function findCodex() {
  if (process.env.CODEX_BIN) return process.env.CODEX_BIN;

  try {
    return execFileSync("which", ["codex"]).toString().trim();
  } catch {
    return undefined;
  }
}

const codex = findCodex();

/**
 * A checkout with the real scripts and marketplace, and a build that writes
 * dist/ marked with BUILD_ID, or fails when BUILD_FAIL is set.
 */
async function fixture(t: TestContext) {
  const root = await realpath(await mkdtemp(join(tmpdir(), "dev-plugin-")));
  t.onTestFinished(() => rm(root, { recursive: true, force: true }));

  const checkout = join(root, "checkout");
  const codexHome = join(root, "codex-home");

  await mkdir(join(checkout, "scripts"), { recursive: true });
  await mkdir(join(checkout, ".agents/plugins"), { recursive: true });
  await mkdir(codexHome);

  for (const file of [
    "scripts/dev-plugin.mjs",
    "scripts/assemble-release.mjs",
    ".agents/plugins/marketplace.json",
    "plugin.json",
  ]) {
    await copyFile(file, join(checkout, file));
  }

  await writeFile(
    join(checkout, "package.json"),
    JSON.stringify({
      name: "subagent-extension-for-codex",
      version: "0.1.0",
      type: "module",
      files: ["dist", "plugin.json"],
      scripts: { build: "node build.mjs" },
    }),
  );

  await writeFile(
    join(checkout, "build.mjs"),
    `import { mkdirSync, rmSync, writeFileSync } from "node:fs";
if (process.env.BUILD_FAIL) process.exit(1);
rmSync("dist", { recursive: true, force: true });
mkdirSync("dist");
for (const file of ["main.js", "stdio.js", "app.html", process.env.BUILD_ID]) {
  writeFileSync("dist/" + file, "");
}
`,
  );

  const env = { ...process.env, CODEX_HOME: codexHome, CODEX_BIN: codex };

  return {
    root,
    checkout,
    /** Runs the script and reports its status instead of throwing. */
    devPlugin: (operation: string, extra: Record<string, string> = {}) =>
      exec(process.execPath, ["scripts/dev-plugin.mjs", operation], {
        cwd: checkout,
        env: { ...env, ...extra },
      }).then(
        ({ stdout }) => ({ code: 0, stdout, stderr: "" }),
        (error: { code: number; stdout: string; stderr: string }) => error,
      ),
    codex: (...args: string[]) => exec(codex!, args, { env }),
    /** The installed copy's dist/ files. */
    installed: () =>
      readdir(
        join(
          codexHome,
          "plugins/cache/demo-user/subagent-extension-for-codex/0.1.0/dist",
        ),
      ),
  };
}

// The script runs the Codex CLI directly, which Windows' npm shims don't allow.
describe.skipIf(!codex || process.platform === "win32")(
  "dev plugin script with the Codex CLI",
  () => {
    test("installs, replaces a same-version build and uninstalls twice", async (t) => {
      const { devPlugin, codex, installed } = await fixture(t);

      assert.equal((await devPlugin("install", { BUILD_ID: "one" })).code, 0);
      assert.equal((await devPlugin("install", { BUILD_ID: "two" })).code, 0);
      assert.equal((await devPlugin("update", { BUILD_ID: "three" })).code, 0);

      // The new build replaces the cached copy, dropping files it no longer has.
      assert.deepEqual((await installed()).sort(), [
        "app.html",
        "main.js",
        "stdio.js",
        "three",
      ]);

      assert.equal((await devPlugin("uninstall")).code, 0);
      assert.equal((await devPlugin("uninstall")).code, 0);

      const { stdout } = await codex(
        "plugin",
        "marketplace",
        "list",
        "--json",
      );

      assert.deepEqual(JSON.parse(stdout).marketplaces, []);
      await assert.rejects(installed());
    });

    test("replaces a marketplace of the same name from another source", async (t) => {
      const { root, checkout, devPlugin, codex, installed } = await fixture(t);

      assert.equal((await devPlugin("install", { BUILD_ID: "other" })).code, 0);
      await cp(join(checkout, "release"), join(root, "other"), {
        recursive: true,
      });
      await devPlugin("uninstall");
      await codex("plugin", "marketplace", "add", join(root, "other"));
      await codex("plugin", "add", plugin);

      const result = await devPlugin("install", { BUILD_ID: "local" });

      assert.equal(result.code, 0, result.stderr);
      assert.match(result.stdout, /Replacing marketplace demo-user/);
      assert.ok((await installed()).includes("local"));

      const { stdout } = await codex(
        "plugin",
        "marketplace",
        "list",
        "--json",
      );

      assert.equal(
        JSON.parse(stdout).marketplaces[0].marketplaceSource.source,
        join(checkout, "release"),
      );
    });

    test("leaves the installation when the build fails", async (t) => {
      const { devPlugin, installed } = await fixture(t);

      assert.equal((await devPlugin("install", { BUILD_ID: "one" })).code, 0);

      const result = await devPlugin("update", { BUILD_FAIL: "1" });

      assert.notEqual(result.code, 0);
      assert.ok((await installed()).includes("one"));
    });

    test("stops with a Codex CLI failure", async (t) => {
      const { root, devPlugin } = await fixture(t);
      const failing = join(root, "codex");

      await writeFile(
        failing,
        `#!/bin/sh\nif [ "$1 $2" = "plugin add" ]; then echo "add failed" >&2; exit 3; fi\nexec "${codex}" "$@"\n`,
      );

      await chmod(failing, 0o755);

      const result = await devPlugin("install", {
        BUILD_ID: "one",
        CODEX_BIN: failing,
      });

      assert.equal(result.code, 3);
      assert.match(result.stderr, /add failed/);
      assert.doesNotMatch(result.stdout, /Installed/);
    });
  },
);

