export function compareVersions(a: string, b: string) {
  const parse = (version: string) => {
    const [core = "", ...pre] = version.replace(/\+.*/, "").split("-");
    const prerelease = pre.join("-");

    return {
      core: core.split(".").map((part) => Number(part) || 0),
