file.content:
// Installs this checkout's build as the Codex plugin, or removes it:
//   npm run dev:plugin -- install|update|uninstall
// install and update are the same: they build, assemble release/ and install
// it from a local marketplace, replacing any marketplace with the same name.
// uninstall removes the plugin and that marketplace. Task data lives outside
// the plugin, so it stays. See docs/development.md#install-a-local-build.
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

const [operation, ...extra] = process.argv.slice(2);

if (!["install", "update", "uninstall"].includes(operation) || extra.length) {
  console.error("Usage: npm run dev:plugin -- install|update|uninstall");
  process.exit(1);
}

const marketplace = JSON.parse(
  readFileSync(".agents/plugins/marketplace.json", "utf8"),
).name;

const { name } = JSON.parse(readFileSync("package.json", "utf8"));
const plugin = `${name}@${marketplace}`;
const codex = process.env.CODEX_BIN || "codex";

// Under npm, its own script runs through this Node, as in assemble-release.mjs.
const npmCli = process.env.npm_execpath;
const npm = npmCli?.endsWith(".js") ? [process.execPath, npmCli] : ["npm"];

/** Runs a command with its output shown, and exits with its status on failure. */
function run(command, args) {
  const { status, error } = spawnSync(command, args, { stdio: "inherit" });

  if (error) throw error;
  if (status !== 0) process.exit(status ?? 1);
}

/**
 * Removes the plugin, then its marketplace. `plugin remove` succeeds when the
 * plugin is absent, and also clears an entry whose marketplace is already
 * gone. Neither step lists state first, since listing fails while a configured
 * local marketplace's directory is missing.
 */
function uninstall() {
  run(codex, ["plugin", "remove", plugin]);

  const { status, error, stderr } = spawnSync(
    codex,
    ["plugin", "marketplace", "remove", marketplace],
    { stdio: ["inherit", "inherit", "pipe"], encoding: "utf8" },
  );

  if (error) throw error;

  // Codex's whole error for a marketplace that isn't configured, which is the
  // goal. Any other output, even with this line in it, is a real failure.
  const absent =
    status === 1 &&
    stderr.trim() ===
      `Error: marketplace \`${marketplace}\` is not configured or installed`;

  if (status !== 0 && !absent) {
    process.stderr.write(stderr);
    process.exit(status ?? 1);
  }
}

if (operation === "uninstall") {
  uninstall();

  console.log(`Uninstalled ${plugin}. Task data is kept.
To use the published plugin, run:
  codex plugin marketplace add demo-user/subagent-extension-for-codex
  codex plugin add ${plugin}`);

  process.exit(0);
}

// Build before touching the installation, so a failed build leaves it working.
run(npm[0], [...npm.slice(1), "run", "build"]);
run(process.execPath, ["scripts/assemble-release.mjs"]);

// Codex refuses a second source under the same name, such as the published
// marketplace, so start from neither.
uninstall();
run(codex, ["plugin", "marketplace", "add", resolve("release")]);
run(codex, ["plugin", "add", plugin]);

console.log(`
Installed ${plugin} from release/.
Reopen the panel to load its new build. Restart Codex to load the new proxy
and skills. A running service at the same version keeps its old code, even
after a Codex restart. To run the new service code, stop that service (the pid
in its service.json), which interrupts its running turns.`);

