// The plugin's data directory. Like the plugin, this ignores the checkout's
// .env, which should give development its own directory.
const data = process.env.SUBAGENT_EXTENSION_FOR_CODEX_DATA
  ? resolve(process.env.SUBAGENT_EXTENSION_FOR_CODEX_DATA)
  : join(homedir(), ".local", "share", "subagent-extension-for-codex");

/**
 * The running service a stdio proxy started on the data directory, proven
 * by its answer to a token challenge before the token is sent. Otherwise
 * `{ absent }` when no service runs, or `{ refused }` with the reason it
 * can't be drained.
 */
async function pluginService() {
  let url;

  try {
    url = new URL(
      JSON.parse(readFileSync(join(data, "service.json"), "utf8")).origin,
    );
  } catch (error) {
    if (error.code === "ENOENT") return { absent: true };

    return { refused: `Could not read ${join(data, "service.json")}.` };
  }

  if (
    url.protocol !== "http:" ||
    !["127.0.0.1", "localhost", "[::1]"].includes(url.hostname) ||
    url.username ||
    url.password
  ) {
    return { refused: `service.json names a non-loopback origin, ${url}.` };
  }

  const { origin } = url;
  const challenge = newChallenge();
  let health;

  try {
    const response = await fetch(`${origin}/health`, {
      headers: { [challengeHeader]: challenge },
      signal: AbortSignal.timeout(2000),
      redirect: "error",
    });

    health = await response.json();
  } catch (error) {
    if (error.cause?.code === "ECONNREFUSED") return { absent: true };

    return {
      refused: `The service at ${origin} didn't answer. Inspect ${join(data, "service.log")}.`,
    };
  }

  let token;

  try {
    token =
      process.env.SUBAGENT_EXTENSION_FOR_CODEX_TOKEN ??
      readFileSync(join(data, "admin-token"), "utf8").trim();
  } catch {
    return { refused: `Could not read ${join(data, "admin-token")}.` };
  }

  if (
    health?.service !== "subagent-extension-for-codex" ||
    !provesToken(token, challenge, health.proof)
  ) {
    return {
      refused: `The service at ${origin} didn't prove it holds this data directory's admin token.`,
    };
  }

  if (health.launcher !== "stdio") {
    return {
      refused: `The service at ${origin} wasn't started by the plugin, as with npm run dev or npm start. Stop it yourself.`,
    };
  }

  if (health.status === "draining") return { draining: true };

  if (health.status !== "ok") {
    return { refused: `The service at ${origin} is ${health.status}.` };
  }

  return { origin, token };
}

/** Asks a yes or no question, where anything but yes, or closed input, is no. */
async function confirm(question) {
  const readline = createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  const closed = new AbortController();
  readline.once("close", () => closed.abort());

  try {
    const answer = await readline.question(`${question} [y/N] `, {
      signal: closed.signal,
    });

    return /^y(es)?$/i.test(answer.trim());
  } catch (error) {
    if (closed.signal.aborted) return false;
    throw error;
  } finally {
    readline.close();
  }
}

/**
 * Offers to drain the running plugin service, which then exits. Returns
 * false when draining was asked for and failed.
 */
async function offerDrain(question) {
  const found = await pluginService();

  if (found.absent) return true;

  if (found.draining) {
    console.log("The running service is already draining.");

    return true;
  }

  if (found.refused && !stopRequested) {
    console.log(`Left the running service alone. ${found.refused}`);

    return true;
  }

  if (!found.refused && !stopRequested) {
    if (!process.stdin.isTTY || !process.stdout.isTTY) {
      console.log(
        "A plugin service is running. To drain it, rerun with --stop-service.",
      );

      return true;
    }

    const drain = await confirm(
      `${question} Its running turns get up to 10 minutes to finish, and any still running are interrupted.`,
    );

    if (!drain) {
      console.log("Left the running service alone.");

      return true;
    }
  }

  // Check again, since the service may have changed while the question waited.
  const service = found.refused ? found : await pluginService();

  if (service.absent || service.draining) {
    console.log("The service has already stopped or is draining.");

    return true;
  }

  if (service.refused) {
    console.error(`Could not drain the service. ${service.refused}`);

    return false;
  }

  let response;

  try {
    response = await fetch(`${service.origin}/api/service/drain`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${service.token}`,
        "Content-Type": "application/json",
        "X-Subagent-Extension-For-Codex": "1",
      },
      body: "{}",
      signal: AbortSignal.timeout(5000),
      redirect: "error",
    });
  } catch {
    console.error(`Could not reach ${service.origin} to drain the service.`);

    return false;
  }

  if (!response.ok) {
    console.error(`The service refused to drain (${response.status}).`);

    return false;
  }

  const { running } = await response.json();

  console.log(
    `Asked the service to drain. Its ${running} running turn(s) get up to 10 minutes to finish, then it exits.`,
  );

  return true;
}

if (operation === "uninstall") {
  uninstall();

  console.log(`Uninstalled ${plugin}. Task data is kept.
To use the published plugin, run:
  codex plugin marketplace add demo-user/subagent-extension-for-codex
  codex plugin add ${plugin}`);

  if (!(await offerDrain("Also stop the running service?"))) {
    console.error(`${plugin} is uninstalled, but the service wasn't drained.`);
    process.exit(1);
  }

  process.exit(0);
}

// Build before touching the installation, so a failed build leaves it working.
run(npm[0], [...npm.slice(1), "run", "build"]);
run(process.execPath, ["scripts/assemble-release.mjs"]);

// Codex refuses a second source under the same name, such as the published
// marketplace, so start from neither.
uninstall();
run(codex, ["plugin", "marketplace", "add", resolve("release")]);
run(codex, ["plugin", "add", plugin]);

console.log(`
Installed ${plugin} from release/.
Reopen the panel to load its new build. Restart Codex to load the new proxy
and skills. A running service at the same version keeps its old code until it
stops. Once a drained service exits, the next proxy call starts the new one.`);

if (
  !(await offerDrain(
    "Restart the running service so it loads the new build?",
  ))
) {
  console.error(`${plugin} is installed, but the service wasn't drained.`);
  process.exit(1);
}

