// Drains the running plugin service for scripts/dev-plugin.mjs, so the next
// proxy call starts the installed build. Draining uses the service's own
// handoff API, which lets running turns finish for up to 10 minutes and then
// interrupts the rest.
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";
import { createInterface } from "node:readline/promises";

import {
  challengeHeader,
  newChallenge,
  provesToken,
} from "../src/service/platform/service/health-proof.ts";

// The plugin's data directory. Like the plugin, this ignores the checkout's
// .env, which should give development its own directory.
const data = process.env.SUBAGENT_EXTENSION_FOR_CODEX_DATA
  ? resolve(process.env.SUBAGENT_EXTENSION_FOR_CODEX_DATA)
  : join(homedir(), ".local", "share", "subagent-extension-for-codex");

/**
 * The running service a stdio proxy started on the data directory. It must
 * answer a token challenge before the token is sent. `instance` names the
 * process service.json describes, so a later check can tell it was replaced.
 * Otherwise `{ absent }` when none runs, or `{ refused }` with the reason it
 * can't be drained.
 */
async function pluginService() {
  let metadata;

  try {
    metadata = JSON.parse(readFileSync(join(data, "service.json"), "utf8"));
  } catch (error) {
    if (error.code === "ENOENT") return { absent: true };

    return { refused: `Could not read ${join(data, "service.json")}.` };
  }

  let url;

  try {
    url = new URL(metadata.origin);
  } catch {}

  if (
    url?.protocol !== "http:" ||
    !["127.0.0.1", "localhost", "[::1]"].includes(url.hostname) ||
    url.username ||
    url.password
  ) {
    return {
      refused: "service.json doesn't name a plain loopback HTTP origin.",
    };
  }

  const { origin } = url;
  const challenge = newChallenge();
  let health;

  try {
    const response = await fetch(`${origin}/health`, {
      headers: { [challengeHeader]: challenge },
      signal: AbortSignal.timeout(2000),
      redirect: "error",
    });

    health = await response.json();
  } catch (error) {
    if (error.cause?.code === "ECONNREFUSED") return { absent: true };

    return {
      refused: `The service at ${origin} didn't answer as the extension service. Inspect ${join(data, "service.log")}.`,
    };
  }

  let token;

  try {
    token =
      process.env.SUBAGENT_EXTENSION_FOR_CODEX_TOKEN ??
      readFileSync(join(data, "admin-token"), "utf8").trim();
  } catch {
    return { refused: `Could not read ${join(data, "admin-token")}.` };
  }

  if (
    health?.service !== "subagent-extension-for-codex" ||
