// Installs this checkout's build as the Codex plugin, or removes it:
//   npm run dev:plugin -- install|update|uninstall [--stop-service]
// install and update are the same: they build, assemble release/ and install
// it from a local marketplace, replacing any marketplace with the same name.
// uninstall removes the plugin and that marketplace. Task data lives outside
// the plugin, so it stays. Afterwards, the script offers to drain a running
// plugin service, which --stop-service does without asking. See
// docs/development.md#install-a-local-build.
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

import { offerDrain } from "./dev-plugin-service.mjs";

const [operation, ...options] = process.argv.slice(2);
const stopRequested = options[0] === "--stop-service";

if (
  !["install", "update", "uninstall"].includes(operation) ||
  options.length > 1 ||
  (options.length && !stopRequested)
) {
  console.error(
    "Usage: npm run dev:plugin -- install|update|uninstall [--stop-service]",
  );

  process.exit(1);
}

const marketplace = JSON.parse(
if (operation === "uninstall") {
  uninstall();

  console.log(`Uninstalled ${plugin}. Task data is kept.
To use the published plugin, run:
  codex plugin marketplace add demo-user/subagent-extension-for-codex
  codex plugin add ${plugin}`);

  if (!(await offerDrain("Also stop the running service?", stopRequested))) {
    console.error(`${plugin} is uninstalled, but the service wasn't drained.`);
    process.exit(1);
  }

  process.exit(0);
}

// Build before touching the installation, so a failed build leaves it working.
run(npm[0], [...npm.slice(1), "run", "build"]);
run(process.execPath, ["scripts/assemble-release.mjs"]);

// Codex refuses a second source under the same name, such as the published
// marketplace, so start from neither.
uninstall();
run(codex, ["plugin", "marketplace", "add", resolve("release")]);
run(codex, ["plugin", "add", plugin]);

console.log(`
Installed ${plugin} from release/.
Reopen the panel to load its new build. Restart Codex to load the new proxy
and skills. A running service at the same version keeps its old code until it
stops. Once a drained service exits, the next proxy call starts the new one.`);

if (
  !(await offerDrain(
    "Restart the running service so it loads the new build?",
    stopRequested,
  ))
) {
  console.error(`${plugin} is installed, but the service wasn't drained.`);
  process.exit(1);
}
