  /** Proves a different token than the data directory's. */
  wrongProof?: boolean;
  /** Another process takes over service.json after the first health check. */
  replaced?: boolean;
  /** Answers a drain without confirming it. */
  unconfirmedDrain?: boolean;
};

/**
 * An extension service on loopback for a temporary data directory. It
 * answers /health with a token proof and records drain requests.
 */
async function fakeService(
  t: TestContext,
  data: string,
  options: FakeServiceOptions = {},
) {
  const token = randomBytes(24).toString("hex");
  const seen = { token, healthChecks: 0, drains: [] as string[] };

  const server = createServer((req, res) => {
    if (req.url === "/health") {
      seen.healthChecks++;
      if (options.replaced && seen.healthChecks === 1) describe(2);

      res.setHeader("Content-Type", "application/json");

      res.end(
        JSON.stringify({
          service: "subagent-extension-for-codex",
          status: "ok",
          launcher: options.launcher ?? "stdio",
          proof: healthProof(
            options.wrongProof ? "x".repeat(48) : token,
            String(req.headers[challengeHeader]),
          ),
        }),
      );

      return;
    }

    if (req.method === "POST" && req.url === "/api/service/drain") {
      seen.drains.push(req.headers.authorization ?? "");
      res.writeHead(202, { "Content-Type": "application/json" });

      res.end(
        options.unconfirmedDrain
          ? "{}"
          : JSON.stringify({ status: "draining", running: 1 }),
      );

      return;
    }

    res.writeHead(404).end();
  });

  await new Promise<void>((resolve) =>
    server.listen(0, "127.0.0.1", resolve),
  );

  t.onTestFinished(() => {
    server.closeAllConnections();
    server.close();
  });

  const origin = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;

  /** Writes service.json as process `pid` would. */
  function describe(pid: number) {
    writeFileSync(
      join(data, "service.json"),
      JSON.stringify({ origin, pid, startedAt: `start ${pid}` }),
    );
  }

  describe(1);
  writeFileSync(join(data, "admin-token"), token);

  return seen;
}

/**
 * Runs the script in a terminal through script(1) and answers its question
 * once it appears. Returns what the terminal showed.
 */
async function inTerminal(
  root: string,
  checkout: string,
  env: NodeJS.ProcessEnv,
  args: string[],
  answer: string,
) {
  const output = join(root, "terminal");

  const command = [process.execPath, "scripts/dev-plugin.mjs", ...args]
    .map((part) => `'${part}'`)
    .join(" ");

  const terminal =
    process.platform === "darwin"
      ? `script -q /dev/null ${command}`
      : `script -qec "${command}" /dev/null`;

  await exec(
    "sh",
    [
      "-c",
      `{ i=0; until grep -q "y/N" "$OUTPUT" 2>/dev/null || [ $i -ge 200 ]; do sleep 0.1; i=$((i+1)); done; printf "%s\\n" "$ANSWER"; } | ${terminal} > "$OUTPUT"`,
    ],
    { cwd: checkout, env: { ...env, OUTPUT: output, ANSWER: answer } },
  ).catch(() => {});

  return readFile(output, "utf8");
}

// The fakes are shell scripts.
describe.skipIf(process.platform === "win32")(
  "dev plugin script with a running service",
  () => {
    test("drains the plugin service with --stop-service", async (t) => {
      const { root, data, devPlugin } = await fixture(t);
      const CODEX_BIN = await acceptingCodex(root);

      for (const operation of ["uninstall", "install"]) {
        const service = await fakeService(t, data);

        const result = await devPlugin(`${operation} --stop-service`, {
          CODEX_BIN,
          BUILD_ID: "one",
        });

        assert.equal(result.code, 0, result.stderr);
        assert.deepEqual(service.drains, [`Bearer ${service.token}`]);
        assert.match(result.stdout, /Asked the service to drain/);
      }
    });

    test("leaves the service running without a terminal or --stop-service", async (t) => {
      const { root, data, devPlugin } = await fixture(t);
      const service = await fakeService(t, data);

      const result = await devPlugin("uninstall", {
        CODEX_BIN: await acceptingCodex(root),
      });

      assert.equal(result.code, 0, result.stderr);
      assert.deepEqual(service.drains, []);
      assert.match(result.stdout, /rerun with --stop-service/);
    });

    test("asks in a terminal, where only yes drains", async (t) => {
      const { root, checkout, data, env } = await fixture(t);
      const terminalEnv = { ...env, CODEX_BIN: await acceptingCodex(root) };

      for (const [answer, drains] of [
        ["", 0],
        ["n", 0],
        ["y", 1],
      ] as const) {
        const service = await fakeService(t, data);

        const shown = await inTerminal(
          root,
          checkout,
          terminalEnv,
          ["uninstall"],
          answer,
        );

        assert.match(shown, /Also stop the running service\?.*\[y\/N\]/s);
        assert.equal(service.drains.length, drains, shown);
      }
    });

    test("fails a requested drain the service can't prove or confirm", async (t) => {
      const { root, data, devPlugin } = await fixture(t);
      const CODEX_BIN = await acceptingCodex(root);

      const cases: [FakeServiceOptions, RegExp][] = [
        [{ wrongProof: true }, /didn't prove it holds/],
        [{ launcher: "foreground" }, /wasn't started by the plugin/],
        [{ replaced: true }, /Another service replaced/],
        [{ unconfirmedDrain: true }, /refused to drain \(202\)/],
      ];

      for (const [options, reason] of cases) {
        const service = await fakeService(t, data, options);
        const result = await devPlugin("uninstall --stop-service", { CODEX_BIN });

        assert.equal(result.code, 1, JSON.stringify(options));
        assert.match(result.stderr, reason);
        assert.match(result.stderr, /is uninstalled, but the service wasn't drained/);

        if (!options.unconfirmedDrain) assert.deepEqual(service.drains, []);
        assert.ok(!result.stderr.includes(service.token));
      }
    });

    test("succeeds when no service is running", async (t) => {
      const { root, data, devPlugin } = await fixture(t);
      const CODEX_BIN = await acceptingCodex(root);

      // No service.json, then one for a service that has exited.
      const before = await devPlugin("uninstall --stop-service", { CODEX_BIN });

      assert.equal(before.code, 0, before.stderr);

      const server = createServer();
      await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
      const { port } = server.address() as AddressInfo;
      await new Promise((resolve) => server.close(resolve));

      writeFileSync(
        join(data, "service.json"),
        JSON.stringify({ origin: `http://127.0.0.1:${port}` }),
      );

      const after = await devPlugin("uninstall --stop-service", { CODEX_BIN });

      assert.equal(after.code, 0, after.stderr);
    });

    test("a failed build never checks the service", async (t) => {
      const { root, data, devPlugin } = await fixture(t);
      const service = await fakeService(t, data);

      const result = await devPlugin("install --stop-service", {
        CODEX_BIN: await acceptingCodex(root),
        BUILD_FAIL: "1",
      });

      assert.notEqual(result.code, 0);
      assert.equal(service.healthChecks, 0);
    });
  },
);
