  root: string,
  checkout: string,
  env: NodeJS.ProcessEnv,
  args: string[],
  answer: string,
) {
  const output = join(root, "terminal");

  const command = [process.execPath, "scripts/dev-plugin.mjs", ...args]
    .map((part) => `'${part}'`)
    .join(" ");

  const terminal =
    process.platform === "darwin"
      ? `script -q /dev/null ${command}`
      : `script -qec "${command}" /dev/null`;

  await exec(
    "sh",
    [
      "-c",
      `{ i=0; until grep -q "y/N" "$OUTPUT" 2>/dev/null || [ $i -ge 200 ]; do sleep 0.1; i=$((i+1)); done; printf "%s\\n" "$ANSWER"; } | ${terminal} > "$OUTPUT"`,
