      const { root, data, devPlugin } = await fixture(t);
      const CODEX_BIN = await acceptingCodex(root);

      const cases: [FakeServiceOptions, RegExp][] = [
        [{ wrongProof: true }, /didn't prove it holds/],
        [{ launcher: "foreground" }, /wasn't started by the plugin/],
        [{ replaced: true }, /Another service replaced/],
